import sys
import json
from pathlib import Path

# Stub V3
class Zephyr2AdaptiveSamplerV3:
    def suggest(self, obs):
        return 0.5

# Stub V4
class Zephyr2AdaptiveSamplerV4(Zephyr2AdaptiveSamplerV3):
    def suggest(self, obs):
        return (obs.get('rel_variance', 0) + obs.get('coverage', 0) + obs.get('delta_coverage', 0)) / 3

# Stub V02
class AdaptiveStationV02:
    def __init__(self):
        self.sampler = Zephyr2AdaptiveSamplerV4()

    def suggest(self, obs):
        p_base = self.sampler.suggest(obs)
        token_factor = min(1.0, obs.get('token_remaining_pct', 0.5) * 2)
        return p_base * (1 - obs.get('token_var', 0)) * token_factor

    def prioritize(self, items):
        return {item: self.suggest({'rel_variance': 0.1, 'coverage': val, 'delta_coverage': 0.05, 
                                    'token_var': cost/100000, 'token_remaining_pct': 0.7}) 
                for item, (val, cost) in items.items()}

# v1.0 inheriting from V02
class AdaptiveStationV1(AdaptiveStationV02):
    def optimize_history(self, segments, budget):
        priorities = self.prioritize(segments)
        retained = []
        total_value = 0
        current_cost = 0
        for s in sorted(segments.keys(), key=lambda x: -priorities[x]):
            val, cost = segments[s]
            if current_cost + cost <= budget:
                retained.append(s)
                total_value += val
                current_cost += cost
            else:
                break
        return {'retained': retained, 'total_value': total_value, 'total_cost': current_cost}

segments = {
    'Ticks 1-20': (0.7, 15000),
    'Ticks 21-40': (0.85, 25000),
    'Ticks 41-60': (0.95, 30000),
    'Ticks 61-80': (1.0, 35000),
    'Meta Data': (0.9, 10000),
    'Archive Docs': (0.95, 8000)
}

station = AdaptiveStationV1()
result = station.optimize_history(segments, 80000)

out_path = Path("storage/shared/meta/priorities/AS_v10_history_opt.json")
out_path.write_text(json.dumps(result, indent=2), encoding="utf-8")

print("v1.0 history optimization complete:", result)
